use std::fs
use std::env
use std::process

fn emit(text: string, number: bool, counter: int) -> int {
    if !number {
        print(text)
        return counter
    }
    let mut n: int = counter
    let mut parts: Vec<string> = text.split("\n").collect()
    if text.ends_with("\n") || text.len() == 0 {
        parts.pop()
    }
    for p in parts {
        n += 1
        println("${n:>6}\t${p}")
    }
    n
}

fn main() {
    let mut number = false
    let mut names: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
            continue
        }
        if a == "-n" {
            number = true
        } else {
            names.push(a)
        }
    }
    let mut counter: int = 0
    let mut failed = false
    if names.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for name in names {
            match fs::read_to_string(name) {
                Ok(text) => { counter = emit(text, number, counter) }
                Err(_) => {
                    println("cat: ${name}: No such file")
                    failed = true
                }
            }
        }
    }
    if failed {
        process::exit(1)
    }
}

